'use client';
import { useEffect, useId, useRef, useState, type CSSProperties, type KeyboardEvent, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect } from '../lib/hooks';
import { Flag, type FlagCode } from '../lib/flags';
import { Icon } from '../lib/icons';
import { Swap } from '../lib/motion';
import { useHoverGlide } from '../lib/glide';
import '../designme.css';
import './country-select.css';

/** A country in the list */
export interface CountrySelectCountry {
  /** Its two-letter code, like "DE". Typing the whole code finds it */
  code: string;
  name: string;
  /** Its currency code, like "EUR", shown at the end of the row */
  currency: string;
  /** Your own flag. The countries designme.dev draws (US, GB, DE, FR, NL, IE, IT, JP, CA, SE, AU, ES) don't need one */
  flag?: ReactNode;
}

export interface CountrySelectProps {
  /** Defaults to the twelve countries on designme.dev */
  countries?: CountrySelectCountry[];
  /** The chosen country's code. Defaults to the first country */
  value?: string;
  defaultValue?: string;
  onValueChange?: (code: string) => void;
  /** Whether the list is open. Leave it out to let the field toggle it */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** What is typed in the search box. Opening the list from the field clears it */
  query?: string;
  defaultQuery?: string;
  onQueryChange?: (query: string) => void;
  label?: string;
  /** The quiet line under the field until a country is picked */
  hint?: string;
  /** The line under the field once one is picked */
  pickedHint?: (country: CountrySelectCountry) => string;
  placeholder?: string;
  /** The heading over the full list */
  suggestedLabel?: string;
  emptyLabel?: string;
  className?: string;
}

const COUNTRIES: CountrySelectCountry[] = [
  { code: 'US', name: 'United States', currency: 'USD' }, { code: 'GB', name: 'United Kingdom', currency: 'GBP' },
  { code: 'DE', name: 'Germany', currency: 'EUR' }, { code: 'FR', name: 'France', currency: 'EUR' },
  { code: 'NL', name: 'Netherlands', currency: 'EUR' }, { code: 'IE', name: 'Ireland', currency: 'EUR' },
  { code: 'IT', name: 'Italy', currency: 'EUR' }, { code: 'JP', name: 'Japan', currency: 'JPY' },
  { code: 'CA', name: 'Canada', currency: 'CAD' }, { code: 'ES', name: 'Spain', currency: 'EUR' },
  { code: 'SE', name: 'Sweden', currency: 'SEK' }, { code: 'AU', name: 'Australia', currency: 'AUD' }
];
const DRAWN = new Set(COUNTRIES.map(c => c.code));
const flagOf = (c?: CountrySelectCountry) => <span className="dm-csx-fl">{c?.flag ?? (c && DRAWN.has(c.code) ? <Flag code={c.code as FlagCode} /> : <span className="dm-flag" />)}</span>;

/** A searchable country select with flags and currencies. Type to filter, arrows to move, Enter to pick, Escape to close. */
export function CountrySelect({ countries = COUNTRIES, value, defaultValue, onValueChange, open, defaultOpen = false, onOpenChange, query, defaultQuery = '',
  onQueryChange, label = 'Billing country', hint = 'Used for tax and currency', pickedHint = c => `Prices shown in ${c.currency}`,
  placeholder = 'Search countries', suggestedLabel = 'Suggested', emptyLabel = 'No country found', className }: CountrySelectProps) {
  const [code, setCode] = useControllable(value, defaultValue ?? countries[0]?.code ?? '', onValueChange);
  const [isOpen, setOpen] = useControllable(open, defaultOpen, onOpenChange);
  const [q, setQ] = useControllable(query, defaultQuery, onQueryChange);
  const [picked, setPicked] = useState(false);
  const chosen = countries.find(c => c.code === code);
  const v = q.trim().toLowerCase();
  const shown = countries.filter(c => !v || c.name.toLowerCase().includes(v) || c.code.toLowerCase() === v);

  const root = useRef<HTMLDivElement>(null), field = useRef<HTMLButtonElement>(null), search = useRef<HTMLInputElement>(null), pop = useRef<HTMLDivElement>(null);
  const list = useRef<HTMLDivElement>(null), opts = useRef<(HTMLButtonElement | null)[]>([]);
  const id = useId();
  // Clean's one hover: a highlight that glides to the row under the pointer or the arrows
  useHoverGlide(list, '.dm-csx-o');
  // the highlight starts on the chosen country, and again whenever the list changes or opens
  const [opens, setOpens] = useState(0), [wasOpen, setWasOpen] = useState(isOpen);
  if (wasOpen !== isOpen) { setWasOpen(isOpen); if (isOpen) setOpens(opens + 1); }
  const paint = `${opens}|${v}`;
  const [hi, setHi] = useState({ at: 0, for: '' });
  const at = hi.for === paint ? Math.min(hi.at, shown.length - 1) : Math.max(0, shown.findIndex(c => c.code === code));

  // keep the highlighted row in view by scrolling the list, never the page
  useIsoLayoutEffect(() => {
    const l = list.current, o = opts.current[at]; if (!isOpen || !l || !o) return;
    const lr = l.getBoundingClientRect(), r = o.getBoundingClientRect();
    if (r.top < lr.top) l.scrollTop -= lr.top - r.top; else if (r.bottom > lr.bottom) l.scrollTop += r.bottom - lr.bottom;
  }, [at, isOpen, paint]);

  // the list hangs 6px under the field, or stands 6px over it when the room under it in the window is too short; its height
  // at its tallest decides, so typing a filter never moves it to the other side
  const [place, setPlace] = useState<CSSProperties>({});
  useIsoLayoutEffect(() => {
    const r = root.current, f = field.current, p = pop.current, l = list.current; if (!isOpen || !r || !f || !p || !l) return;
    const b = f.getBoundingClientRect(), tall = p.offsetHeight - l.offsetHeight + (parseFloat(getComputedStyle(l).maxHeight) || l.offsetHeight);
    const up = b.bottom + tall + 12 > innerHeight && b.top - tall - 12 > innerHeight - b.bottom;
    setPlace(up ? { top: 'auto', bottom: r.offsetHeight - f.offsetTop + 6, ['--dm-origin' as string]: 'bottom left' } : { top: f.offsetTop + f.offsetHeight + 6, bottom: 'auto', ['--dm-origin' as string]: 'top left' });
  }, [isOpen]);

  // a click outside closes it
  useEffect(() => {
    if (!isOpen) return;
    const down = (e: PointerEvent) => { if (!root.current?.contains(e.target as Node)) setOpen(false); };
    document.addEventListener('pointerdown', down);
    return () => document.removeEventListener('pointerdown', down);
  }, [isOpen, setOpen]);

  const openList = () => { setQ(''); setOpen(true); requestAnimationFrame(() => search.current?.focus({ preventScroll: true })); };
  const close = (refocus = false) => { setOpen(false); if (refocus) field.current?.focus({ preventScroll: true }); };
  const choose = (c: CountrySelectCountry) => { setCode(c.code); setPicked(true); close(root.current?.contains(document.activeElement) ?? false); };
  const move = (d: number) => { if (shown.length) setHi({ at: (at + d + shown.length) % shown.length, for: paint }); };
  const key = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'ArrowDown') { move(1); e.preventDefault(); }
    else if (e.key === 'ArrowUp') { move(-1); e.preventDefault(); }
    else if (e.key === 'Enter') { if (shown[at]) choose(shown[at]); e.preventDefault(); }
    else if (e.key === 'Escape') close(true);
    // Tab moves on from the search box and closes the list
    else if (e.key === 'Tab') close();
  };

  return (
    <div data-dm="" ref={root} className={cx('dm-csx', className)}>
      <label className="dm-csx-l" htmlFor={`${id}-f`}>{label}</label>
      <button ref={field} id={`${id}-f`} type="button" className="dm-csx-f" aria-haspopup="listbox" aria-expanded={isOpen}
        onClick={() => (isOpen ? close() : openList())} onKeyDown={e => { if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return; e.preventDefault(); if (isOpen) search.current?.focus({ preventScroll: true }); else openList(); }}>
        {flagOf(chosen)}<Swap className="dm-csx-v">{chosen?.name ?? ''}</Swap><Icon name="chev-d" size="xs" />
      </button>
      {/* its search is its first row, the glass on the flags' column and the words on the names' */}
      <div ref={pop} className={cx('dm-pop dm-csx-pop', isOpen && 'dm-open')} inert={!isOpen} style={place}>
        <div className="dm-csx-s">
          <Icon name="search" size="xs" />
          <input ref={search} className="dm-csx-q" placeholder={placeholder} aria-label={placeholder} spellCheck={false} value={q} role="combobox"
            aria-expanded={isOpen} aria-controls={`${id}-list`} aria-autocomplete="list" aria-activedescendant={shown[at] ? `${id}-${shown[at].code}` : undefined}
            onChange={e => setQ(e.target.value)} onKeyDown={key} />
        </div>
        <div ref={list} className="dm-csx-list" role="listbox" id={`${id}-list`} aria-label={label}>
          {!v && <div className="dm-csx-g">{suggestedLabel}</div>}
          {shown.map((c, i) => (
            <button key={c.code} ref={el => { opts.current[i] = el; }} id={`${id}-${c.code}`} type="button" tabIndex={-1} role="option"
              aria-selected={c.code === code} className={cx('dm-csx-o', i === at && 'dm-hl')}
              onMouseEnter={() => setHi({ at: i, for: paint })} onClick={() => choose(c)}>
              {flagOf(c)}{c.name}<span className="dm-cd">{c.currency}</span><span className="dm-ck"><Icon name="check" size="xs" /></span>
            </button>
          ))}
          {!shown.length && <div className="dm-csx-g">{emptyLabel}</div>}
        </div>
      </div>
      <Swap className="dm-muted dm-csx-h">{picked && chosen ? pickedHint(chosen) : hint}</Swap>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Country select ---------- */
/* the label, the field and the hint, as wide as the other single fields. The list opens from the field (placePop), and the
   field glides up with it so the two sit centred together (centre()). The field's flag, the search's glass and the rows'
   flags share one column 12px in, and the names another; the currencies end 12px in, before the chosen country's tick */
.dm-csx{width:100%;max-width:var(--dm-field-w);margin:0 auto;display:flex;flex-direction:column;gap:6px;position:relative}
.dm-csx-l{font-size:12.5px;font-weight:500}
.dm-csx-f{display:flex;align-items:center;gap:10px;height:var(--dm-field-h);padding:0 var(--dm-s-3);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font-size:13.5px;text-align:left;transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dm-csx-f{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
/* a dropdown's field steps up its edge while it has the keyboard's focus or its list is open; it takes no ring */
.dm-csx-f:focus-visible{outline:0}
.dm-csx-f:is(:focus-visible,[aria-expanded="true"]){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-csx-v{flex:1}
.dm-csx-f>svg{color:var(--dm-muted);transition:transform .35s var(--dm-ease)}
.dm-csx-f[aria-expanded="true"]>svg{transform:rotate(180deg)}
.dm-csx-fl{display:grid;place-items:center;flex:none;width:20px}
.dm-csx-h{font-size:12px;transition:opacity var(--dm-t-fast) var(--dm-ease)}
/* the open list covers the hint under the field, so the hint steps aside rather than peeking out at the list's corner */
.dm-csx:has(.dm-csx-pop.dm-open) .dm-csx-h{opacity:0}
/* closed, the list is hidden as well as clear (.pop), so Tab passes over its search and its countries */
.dm-csx-pop{left:0;right:0;min-width:0;padding:0 6px 6px}
/* the search is the list's first row: its glass on the flags' column, its words on the names', a hairline under it that
   steps up while it has the focus */
.dm-csx-s{display:flex;align-items:center;gap:10px;height:var(--dm-field-h);margin:0 -6px 6px;padding:0 var(--dm-s-3);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-muted);transition:border-color var(--dm-t-fast)}
.dm-csx-s>svg{margin:0 4px}
.dm-csx-s:has(.dm-csx-q:focus){border-bottom-color:color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-csx-q{flex:1;min-width:0;height:100%;border:0;outline:0;background:transparent;padding:0;font:inherit;font-size:13px;color:var(--dm-fg)}
.dm-csx-q::placeholder{color:var(--dm-muted)}
.dm-csx-list{max-height:200px;overflow-y:auto;display:flex;flex-direction:column;gap:2px}
.dm-csx-o{display:flex;align-items:center;gap:10px;padding:7px 6px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;text-align:left;flex:none;transition:background var(--dm-t-fast)}
.dm-csx-o.dm-hl{background:var(--dm-row)}
.dm-csx-o .dm-cd{margin-left:auto;font-size:11.5px;color:var(--dm-muted);transition:color var(--dm-t-fast)}
/* on a highlighted row's grey the currency steps up, so it keeps 4.5:1 and APCA Lc 60 in dark mode */
.dm-csx-o.dm-hl .dm-cd{color:var(--dm-fg2)}
/* every row keeps a place for the tick, so the currencies stand in one column */
.dm-csx-o .dm-ck{display:grid;color:var(--dm-accent-fg,var(--dm-accent));visibility:hidden}
.dm-csx-o[aria-selected="true"] .dm-ck{visibility:visible}
.dm-csx-g{font-size:11.5px;color:var(--dm-muted);padding:6px 6px 2px}
/* Clean (owner, 21 Nov: "almost no difference between soft and clean so make it clearer"). The field is a flat dropdown
   trigger: an off-white fill under a hairline that deepens on hover and while its list is open. The list opens from it with
   Clean's scale and fade, in the menus' 22px corners: its search sits in an off-white head strip, "Suggested" is Clean's
   section label, and the rows are 10px with the one gliding highlight (hoverGlide). The flags, the glass and the label stand
   on one column 16px in; the codes end on the content's right edge, 16px in, and the picked row keeps a stronger fill and its
   tick, in the accent (white in dark), in a column of its own just before its code */
:root[data-style="clean"] .dm-csx-f,:root [data-style="clean"] .dm-csx-f,:root [data-style="clean"].dm-csx-f{background:var(--dm-strip);box-shadow:var(--dm-btn2-depth);transition:box-shadow var(--dm-t-fast) var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-csx-f:hover,:root [data-style="clean"] .dm-csx-f:hover,:root [data-style="clean"].dm-csx-f:hover{background:var(--dm-chip);box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .dm-csx-f:is(:focus-visible,[aria-expanded="true"]),:root [data-style="clean"] .dm-csx-f:is(:focus-visible,[aria-expanded="true"]),:root [data-style="clean"].dm-csx-f:is(:focus-visible,[aria-expanded="true"]){background:var(--dm-chip);box-shadow:var(--dm-btn2-hover)}
:root[data-style="clean"] .dm-csx-f>svg,:root [data-style="clean"] .dm-csx-f>svg,:root [data-style="clean"].dm-csx-f>svg{transition:transform var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .dm-csx-pop,:root [data-style="clean"] .dm-csx-pop,:root [data-style="clean"].dm-csx-pop{border-radius:var(--dm-r-card);padding:0 6px 6px}
:root[data-style="clean"] .dm-csx-s,:root [data-style="clean"] .dm-csx-s,:root [data-style="clean"].dm-csx-s{height:44px;margin:0 -6px 4px;padding:0 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .dm-csx-s:has(.dm-csx-q:focus),:root [data-style="clean"] .dm-csx-s:has(.dm-csx-q:focus),:root [data-style="clean"].dm-csx-s:has(.dm-csx-q:focus){border-bottom-color:var(--dm-line)}
:root[data-style="clean"] .dm-csx-list,:root [data-style="clean"] .dm-csx-list,:root [data-style="clean"].dm-csx-list{gap:2px;max-height:227px}
:root[data-style="clean"] .dm-csx-g,:root [data-style="clean"] .dm-csx-g,:root [data-style="clean"].dm-csx-g{padding:10px 10px 4px;font-size:11.5px;line-height:16px;color:var(--dm-muted)}
:root[data-style="clean"] .dm-csx-o,:root [data-style="clean"] .dm-csx-o,:root [data-style="clean"].dm-csx-o{height:34px;padding:0 10px;border-radius:10px;transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-csx-o[aria-selected="true"],:root [data-style="clean"] .dm-csx-o[aria-selected="true"],:root [data-style="clean"].dm-csx-o[aria-selected="true"]{background:var(--dm-row-on)}
:root[data-style="clean"] .dm-csx-o .dm-ck,:root [data-style="clean"] .dm-csx-o .dm-ck,:root [data-style="clean"].dm-csx-o .dm-ck{order:1;margin-left:auto}
:root[data-style="clean"] .dm-csx-o .dm-cd,:root [data-style="clean"] .dm-csx-o .dm-cd,:root [data-style="clean"].dm-csx-o .dm-cd{order:2;margin-left:8px;min-width:28px;text-align:right}
/* (on the picked row's stronger grey the code steps up, so it keeps 4.5:1) */
:root[data-style="clean"] .dm-csx-o[aria-selected="true"] .dm-cd,:root [data-style="clean"] .dm-csx-o[aria-selected="true"] .dm-cd,:root [data-style="clean"].dm-csx-o[aria-selected="true"] .dm-cd{color:var(--dm-fg2)}

